// Transaction is the resolver for the transaction field.
func (r *queryResolver) Transaction(ctx context.Context, id string) (*model.TransactionDetail, error) {
	logger := log.LoggerInContext(ctx)

	b, err := middlewares.BusinessFromContext(ctx)
	if err != nil {
		logger.WithError(err).Error("failed to fetch business in context")
		return nil, err
	}

	ownerID := ""
	if b.Edges.Owner != nil {
		ownerID = b.Edges.Owner.ID
	}
	if ownerID == "" {
		owner, err := b.QueryOwner().First(ctx)
		if err == nil && owner != nil {
			ownerID = owner.ID
		}
	}

	return r.Services.TransactionService.GetTransactionByID(ctx, id, ownerID)
}
